CREATE TABLE IF NOT EXISTS ai_tasks (id VARCHAR(32) PRIMARY KEY,project_id VARCHAR(32) NOT NULL,task_type VARCHAR(40) NOT NULL,status VARCHAR(20) NOT NULL,progress INT NOT NULL,message VARCHAR(500) NOT NULL,result JSON NULL,error TEXT NOT NULL,created_at DATETIME(6) NOT NULL,started_at DATETIME(6) NULL,ended_at DATETIME(6) NULL,INDEX idx_tasks_project_created(project_id,created_at),INDEX idx_tasks_status(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS task_events (task_id VARCHAR(32) NOT NULL,event_id BIGINT UNSIGNED NOT NULL,event_type VARCHAR(50) NOT NULL,progress INT NOT NULL,message VARCHAR(500) NOT NULL,created_at DATETIME(6) NOT NULL,PRIMARY KEY(task_id,event_id),CONSTRAINT fk_task_events_task FOREIGN KEY(task_id) REFERENCES ai_tasks(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
